'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const textBlock=text=>({id:id(),type:'paragraph',text});
const imgBlock=(src,alt)=>({id:id(),type:'image',src,alt});
const samples=[
{id:'sample-pose',title:'ポーズから、表情が生まれる。',tags:['VRM','作品'],date:'2022-05-01T12:00',sample:true,blocks:[imgBlock('assets/pose.png','既存ブログの基本立ちポーズ'),textBlock('展示レイアウトの見本です。既存ブログのポーズ画像を、余白のある額装のように並べます。')]},
{id:'sample-note',title:'',tags:['考えごと'],date:'2026-11-15T12:00',sample:true,blocks:[textBlock('完成していなくても、\nタイトルが決まっていなくても。\n\n途中のかたちを、そのまま残せる場所に。\n\nこれは短文表示の試作用テキストです。')]},
{id:'sample-gallery',title:'同じモデル、違うしぐさ。',tags:['VRM','作品'],date:'2022-05-01T11:00',sample:true,blocks:[imgBlock('assets/peace.png','既存ブログのWピース'),imgBlock('assets/style.png','既存ブログの立ちポーズ'),textBlock('複数画像をまとめた投稿の見本。画像をクリックして個別ページの組み方も確認できます。')]},
{id:'sample-article',title:'VRM1.0の表情について',tags:['VRM','技術の記録'],date:'2022-10-23T11:34',sample:true,blocks:[imgBlock('assets/expression.jpg','VRM1.0の表情に関する既存記事の画像'),textBlock('既存記事を新しい読み物のレイアウトで見せるための見本です。全文移行はまだ行っていません。'),{id:id(),type:'heading',text:'作品と、制作の記録を一緒に。'},textBlock('見出し、文章、画像、引用、リンクを同じ投稿の中に配置できます。長文は読みやすい本文幅で表示し、一覧では最初の文章だけを概要にします。'),{id:id(),type:'quote',text:'画像から書きはじめても、文章から書きはじめても、同じ一つの記録です。'}, {id:id(),type:'link',text:'既存サイトの原文を読む',url:'https://brand-new.tokyo/vrm1-expression'}]},
{id:'sample-cover',title:'ポーズを集める、小さな展示。',tags:['VRM','作品'],date:'2022-05-01T10:00',sample:true,blocks:[imgBlock('assets/cover.jpg','既存ブログのポーズ集の紹介画像'),textBlock('こちらは作品集カードの試作見本です。現在の作品集は、同じテーマの投稿を絞り込む方式です。')]},
{id:'sample-thought',title:'書き足していく、制作ノート',tags:['制作記録'],date:'2026-11-15T10:00',sample:true,blocks:[textBlock('最初は一枚だけ。\nあとから気づいたことや、次の画像を加えていく。'),{id:id(),type:'heading',text:'まだ途中、を残す'},textBlock('試作の投稿は「編集する」から書き足せます。元の見本はそのままに、編集した内容が端末内の投稿として作られます。')]}
];
let state={draft:null,posts:[]}, db,view='all',search='',tag='',draftsOnly=false,collections=false,editing=null,detailPost=null,queued=Promise.resolve(),dirty=false;
const message=t=>{ $('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(message.timer);message.timer=setTimeout(()=>$('#toast').hidden=true,4500); };
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('bnt-design-lab-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onerror=()=>reject(r.error);r.onsuccess=()=>resolve(r.result);});}
function readDB(){return new Promise((resolve,reject)=>{const r=db.transaction('state').objectStore('state').get('main');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function persist(){dirty=true;$('#saveState').textContent='端末内に保存中…';const snapshot=structuredClone(state);const job=queued.catch(()=>{}).then(()=>new Promise((resolve,reject)=>{if(!db)return reject(Error('DB unavailable'));const tx=db.transaction('state','readwrite');tx.objectStore('state').put(snapshot,'main');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);}));queued=job;job.then(()=>{if(queued===job){dirty=false;$('#saveState').textContent='この端末に下書きを保存済み';}}).catch(()=>{$('#saveState').textContent='保存できませんでした。書き出して保管してください';message('端末内への保存に失敗しました。下書きを書き出してください。');});return job;}
function collect(){if(!editing)return;editing.title=$('#title').value;editing.tags=$('#tags').value.split(/[,、]/).map(x=>x.trim()).filter(Boolean);editing.date=$('#date').value;state.draft=structuredClone(editing);persist().catch(()=>{});live();}
function localDate(){const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16);}
function imgCount(p){return p.blocks.filter(x=>x.type==='image').length;}
function prose(p){return p.blocks.filter(x=>x.type==='paragraph'||x.type==='quote').map(x=>x.text).join('\n');}
function dateLabel(p){return p.date?esc(p.date.slice(0,10).replaceAll('-','.')):'日付なし';}
function allPosts(){return [...state.posts,...samples];}
function render(){
 const pool=draftsOnly?(state.draft?[state.draft]:[]):allPosts();
 const visible=pool.filter(p=>(view!=='images'||imgCount(p)>0)&&(view!=='articles'||prose(p).trim())&&(!tag||p.tags.includes(tag))&&(!search||[p.title,prose(p),...p.tags].join(' ').toLowerCase().includes(search.toLowerCase())));
 $('#feed').dataset.view=view;$('#empty').hidden=visible.length>0;
 $('#feed').innerHTML=visible.map(p=>{const imgs=p.blocks.filter(x=>x.type==='image');return `<article class="post ${imgs.length?'hasimage':'textonly'}" tabindex="0" role="button" aria-label="${esc(p.title||prose(p).slice(0,35)||'画像の投稿')}を開く" data-id="${esc(p.id)}">${imgs.length?`<div class="postimage ${imgs.length>1?'multiple':''}">${imgs.slice(0,2).map(i=>`<img src="${esc(i.src)}" alt="${esc(i.alt||'投稿画像')}" loading="lazy">`).join('')}</div>`:''}<div class="postbody"><div class="postmeta"><span>${dateLabel(p)}</span><span>${draftsOnly?'下書き':p.sample?'レイアウト見本':'端末内の試作投稿'}</span></div>${p.title?`<h2>${esc(p.title)}</h2>`:''}<p class="excerpt">${esc(prose(p).slice(0,view==='articles'?180:100))}${prose(p).length>100&&view!=='articles'?'…':''}</p><span class="tag">${p.tags.map(esc).join(' ／ ')}</span>${p.blocks.length>3?'<span class="articlehint">続きをひらく ↗</span>':''}</div></article>`;}).join('');
 $$('#feed .post').forEach(el=>{el.onclick=()=>draftsOnly?openEditor():openDetail(pool.find(x=>x.id===el.dataset.id));el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click();}};});
 $('#themebar').innerHTML=collections?['すべて',...new Set(allPosts().flatMap(p=>p.tags))].map(t=>`<button class="${(t==='すべて'&&!tag)||tag===t?'selected':''}" data-tag="${esc(t)}">${esc(t)}</button>`).join(''):'';
 $$('#themebar button').forEach(b=>b.onclick=()=>{tag=b.dataset.tag==='すべて'?'':b.dataset.tag;render();});
}
function renderContent(p){return `<div class="rendered"><p class="small">${dateLabel(p)}　${p.tags.map(esc).join(' ／ ')}</p>${p.title?`<h1>${esc(p.title)}</h1>`:''}${p.blocks.map(b=>b.type==='image'?`<figure><img src="${esc(b.src)}" alt="${esc(b.alt||'投稿画像')}">${b.alt?`<figcaption>${esc(b.alt)}</figcaption>`:''}</figure>`:b.type==='heading'?`<h2>${esc(b.text)}</h2>`:b.type==='quote'?`<blockquote>${esc(b.text)}</blockquote>`:b.type==='link'?`<p>${/^https?:\/\//i.test(b.url)?`<a href="${esc(b.url)}" target="_blank" rel="noopener noreferrer">${esc(b.text||b.url)} ↗</a>`:'リンク先は https:// または http:// から入力してください'}</p>`:`<p>${esc(b.text)}</p>`).join('')}</div>`;}
function live(){$('#livePreview').innerHTML=renderContent(editing);}
function openDetail(p,preview=false){detailPost=p;$('#detailLabel').textContent=preview?'公開前の見え方（外部公開はしません）':p.sample?'レイアウト見本':'端末内の試作投稿';$('#detailContent').innerHTML=renderContent(p);$('#detailActions').innerHTML=preview?'':`<button id="editDetail">${p.sample?'この見本を下書きにする':'編集する'}</button>${p.sample?'':'<button id="privateDetail">一覧から下書きに戻す</button>'}`;if(!preview){$('#editDetail').onclick=()=>{if(state.draft&&state.draft.id!==p.id){message('編集中の下書きがあります。「下書き」から続きを編集してください。');return;}$('#detail').close();openEditor(p);};if($('#privateDetail'))$('#privateDetail').onclick=async()=>{if(state.draft&&state.draft.id!==p.id){message('先に現在の下書きを一覧へ置くか、編集を続けてください。');return;}state.draft=structuredClone(p);state.posts=state.posts.filter(x=>x.id!==p.id);await persist().catch(()=>{});$('#detail').close();render();message('端末内の下書きに戻しました');};}$('#detail').showModal();}
function openEditor(p){editing=structuredClone(p?(p.sample?{...p,id:id(),sample:false}:p):(state.draft||{id:id(),title:'',tags:[],date:localDate(),blocks:[textBlock('')]}));$('#title').value=editing.title;$('#tags').value=editing.tags.join('、');$('#date').value=editing.date;drawBlocks();live();$('#editor').showModal();collect();}
function drawBlocks(){
 $('#blocks').innerHTML=editing.blocks.map((b,i)=>`<div class="block" data-index="${i}"><div class="blockbar"><span>${({paragraph:'文章',heading:'見出し',quote:'引用',link:'リンク',image:'画像'})[b.type]}</span><button data-move="-1" ${i===0?'disabled':''} aria-label="上へ移動">↑</button><button data-move="1" ${i===editing.blocks.length-1?'disabled':''} aria-label="下へ移動">↓</button><button data-remove aria-label="このブロックを取り除く">取り除く</button></div>${b.type==='image'?`<img src="${esc(b.src)}" alt="${esc(b.alt)}"><input data-field="alt" aria-label="画像の説明" placeholder="画像の説明（任意）" value="${esc(b.alt)}">`:b.type==='link'?`<input data-field="text" aria-label="リンクの表示名" placeholder="リンクの表示名" value="${esc(b.text)}"><input data-field="url" aria-label="リンク先URL" placeholder="https://" value="${esc(b.url)}">`:`<textarea data-field="text" aria-label="${b.type==='paragraph'?'文章':b.type==='heading'?'見出し':'引用'}" placeholder="思いついたことを、そのまま。">${esc(b.text)}</textarea>`}</div>`).join('');
 $$('#blocks .block').forEach(el=>{const i=Number(el.dataset.index);el.querySelectorAll('[data-field]').forEach(input=>input.oninput=()=>{editing.blocks[i][input.dataset.field]=input.value;collect();});el.querySelectorAll('[data-move]').forEach(btn=>btn.onclick=()=>{const n=i+Number(btn.dataset.move);[editing.blocks[i],editing.blocks[n]]=[editing.blocks[n],editing.blocks[i]];drawBlocks();collect();});el.querySelector('[data-remove]').onclick=()=>{const removed=editing.blocks.splice(i,1)[0];drawBlocks();collect();message('ブロックを取り除きました');const undo=document.createElement('button');undo.textContent='元に戻す';undo.style.color='white';undo.onclick=()=>{editing.blocks.splice(i,0,removed);drawBlocks();collect();$('#toast').hidden=true;};$('#toast').append(' ',undo);clearTimeout(message.timer);message.timer=setTimeout(()=>$('#toast').hidden=true,15000);};});
}
function add(type){editing.blocks.push(type==='link'?{id:id(),type,text:'',url:''}:{id:id(),type,text:''});drawBlocks();collect();$('#blocks .block:last-child textarea, #blocks .block:last-child input')?.focus();}
async function addFiles(files){let bytes=editing.blocks.reduce((n,b)=>n+(b.bytes||0),0);for(const f of files){if(!['image/jpeg','image/png','image/webp','image/gif'].includes(f.type)||f.size>8*1024*1024||bytes+f.size>30*1024*1024){message('この画像は追加できません。形式と容量をご確認ください。');continue;}try{const src=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(f);});await new Promise((res,rej)=>{const im=new Image();im.onload=res;im.onerror=rej;im.src=src;});editing.blocks.push({...imgBlock(src,''),bytes:f.size});bytes+=f.size;}catch{message('画像を読み取れませんでした。');}}drawBlocks();collect();$('#file').value='';}
$$('[data-theme]').forEach(b=>b.onclick=()=>{document.body.classList.toggle('journal',b.dataset.theme==='journal');$$('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));render();});
$('#search').oninput=e=>{search=e.target.value;render();};
$('#newButton').onclick=()=>openEditor();$('#quickText').onclick=()=>openEditor();$('#quickImage').onclick=()=>{openEditor();$('#file').click();};$('#addImage').onclick=()=>$('#file').click();$('#file').onchange=e=>addFiles(e.target.files);
$('#addText').onclick=()=>add('paragraph');$('#addHeading').onclick=()=>add('heading');$('#addQuote').onclick=()=>add('quote');$('#addLink').onclick=()=>add('link');
[$('#title'),$('#tags'),$('#date')].forEach(x=>x.oninput=collect);
$('#closeEditor').onclick=()=>{collect();$('#editor').close();render();};$('#editor').addEventListener('cancel',()=>{collect();render();});$('#closeDetail').onclick=()=>$('#detail').close();$('#previewButton').onclick=()=>openDetail(editing,true);
$('#publishButton').onclick=async()=>{if(!editing.blocks.some(b=>b.type==='image'||(b.text||'').trim())){message('画像か文章をひとつ追加してください。');return;}collect();const next=structuredClone(editing);state.posts=[next,...state.posts.filter(x=>x.id!==next.id)];state.draft=null;try{await persist();$('#editor').close();nav('home');message('試作の一覧に置きました。外部には公開されません。');}catch{state.draft=next;}};
$('#exportButton').onclick=()=>{const data=JSON.stringify({schemaVersion:1,prototype:true,post:editing},null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='brand-new-tokyo-draft.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
function nav(mode){draftsOnly=mode==='draft';collections=mode==='collections';tag='';$$('header nav button').forEach(x=>x.classList.remove('navactive'));$(mode==='draft'?'#draftButton':mode==='collections'?'#collectionButton':'#homeButton').classList.add('navactive');render();}
$('#homeButton').onclick=()=>nav('home');$('#collectionButton').onclick=()=>nav('collections');$('#draftButton').onclick=()=>{nav('draft');if(state.draft)openEditor();else message('まだ下書きはありません。画像や文章から始められます。');};$('#randomButton').onclick=()=>{const p=allPosts();openDetail(p[Math.floor(Math.random()*p.length)]);};
$('#editor').addEventListener('dragover',e=>e.preventDefault());$('#editor').addEventListener('drop',e=>{e.preventDefault();if(e.dataTransfer.files.length)addFiles(e.dataTransfer.files);});window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{db=await openDB();const saved=await readDB();if(saved?.posts&&Array.isArray(saved.posts))state=saved;}catch{message('端末保存が使えません。下書きの書き出しをご利用ください。');}render();})();
